mapper.select:
select t.name as trainerName, u.tel as trainerTel, u.created_at as regDate, ifnull(count(distinct m.id),0) as trainerClientCount, ifnull(sum(p.payment_price*0.9),0) as trainerCal from trainer t left join user u on(t.user_id=u.id) left join member m on(t.id=m.trainer_id) left join payment p on(p.user_id=t.user_id)
And t.name like concat('%', #{trainerName}, '%')
group by t.name, u.tel, u.created_at order by t.name limit #{row}, #{pageRow}

select m.name as clientName, u.tel as clientTel, u.created_at as regDate, m.trainer_id as ptTrainer, ifnull(sum(p.payment_price),0) as payment from member m left join user u on(m.user_id=u.id) left join payment p on(p.user_id=m.user_id)
And m.name like concat('%', #{clientName}, '%')
group by m.name, u.tel, u.created_at, m.trainer_id order by m.name limit #{row}, #{pageRow}

SELECT u.name AS name, u.email_id AS email, u.tel AS tel, u.profileImg as profileImg,
t.address AS address,
'' AS address_detail, t.business_registration_num AS bizNum, t.br_file AS authDoc FROM user u JOIN trainer t ON u.id = t.user_id WHERE u.id = #{userId}
